{
  "title": "Discussion on tax filing, domain purchase, and app viability",
  "topics": [
    {
      "id": "tax-filing-assistance",
      "title": "Tax filing assistance and penalties",
      "claims": [
        {
          "text": "P1 paid about 1000 грн to refile correctly with the help of aunt Sveta, avoiding larger fines.",
          "evidence": [1]
        },
        {
          "text": "The process of correcting declarations takes about an hour with Excel, once per month.",
          "evidence": [5, 6]
        },
        {
          "text": "Quarterly reports must be filed correctly to avoid issues.",
          "evidence": [7]
        },
        {
          "text": "Mistakes often come from mis‑labeling columns rather than tax calculation errors.",
          "evidence": [8]
        }
      ]
    },
    {
      "id": "domain-and-calculator",
      "title": "Domain purchase and calculator need",
      "claims": [
        {
          "text": "P2 has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "P2 mentions a “FOP calculator” as a needed tool.",
          "evidence": [3]
        },
        {
          "text": "P1 suggests that buying the calculator will free money for a domain.",
          "evidence": [4]
        },
        {
          "text": "P4 thinks buying a domain is unnecessary.",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a cross‑platform app",
      "claims": [
        {
          "text": "Web is the simplest platform but less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO for a web product is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic sources (Instagram, X, Threads) or ad revenue are available.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because of early paywall barriers.",
          "evidence": [11]
        },
        {
          "text": "A successful approach mentioned in a podcast includes fast delivery (< 1 week) and using a cross‑platform stack like Flutter.",
          "evidence": [12]
        },
        {
          "text": "P4 doubts that anyone will pay 299 грн for the product without proof of demand.",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "calculator-currency-limit",
      "title": "Currency limitation of the calculator",
      "claims": [
        {
          "text": "The calculator only works with Ukrainian‑hryvnia (UAH) FOP; P1 had to convert all transactions using the daily exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "scam-discussion",
      "title": "Allegations of scam and password access",
      "claims": [
        {
          "text": "P4 claims the app’s source code and password are publicly accessible and that the product is effectively a scam.",
          "evidence": [21, 22, 23, 24, 30, 32, 33, 34]
        },
        {
          "text": "P5 jokes about piracy and suggests asking the developer for the password.",
          "evidence": [25, 27]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app without trouble.",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there enough demand (e.g., at least ten people willing to pay 299 грн) to justify developing the app?",
      "evidence": [20]
    },
    {
      "text": "Should the team invest in buying a domain before the calculator is acquired?",
      "evidence": [2, 4, 9, 10]
    }
  ]
}
